import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next() + "0"; // sentinel digit closes the last letter segment
        // Digits split the string into letter-only segments; a segment counts if it has an uppercase letter.
        int best = -1, start = 0;
        for (int i = 0; i < s.length(); i++)
            if (Character.isDigit(s.charAt(i))) {
                boolean upper = false;
                for (int k = start; k < i; k++) upper |= Character.isUpperCase(s.charAt(k));
                if (upper) best = Math.max(best, i - start);
                start = i + 1;
            }
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := nextToken() + "0" // sentinel digit closes the last letter segment
	// Digits split the string into letter-only segments; a segment counts if it has an uppercase letter.
	best, start := -1, 0
	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			upper := false
			for k := start; k < i; k++ {
				upper = upper || (s[k] >= 'A' && s[k] <= 'Z')
			}
			if upper {
				best = max(best, i-start)
			}
			start = i + 1
		}
	}
	fmt.Println(best)
}
